#include <stdio.h>
#include <stdlib.h>

struct Link {
  int value;
  Link *next;
};

void del_x(Link *&L, int x) {
  if (!L)
    return;
  Link *pre;
  if (x == L->value) {
    pre = L;
    L = L->next;
    free(pre);
    del_x(L, x);
  } else {
    del_x(L->next, x);
  }
}

Link *creat_link_tail() {
  Link *head = (Link *)malloc(sizeof(Link));
  Link *rear = (Link *)malloc(sizeof(Link));
  head = rear;
  int value;
  scanf("%d", &value);
  while (value != 9999) {
    Link *p = (Link *)malloc(sizeof(Link));
    p->value = value;
    rear->next = p;
    rear = p;
    scanf("%d", &value);
  }
  rear->next = NULL;
  return head;
}

void print_link(Link *L) {
  Link *p = L->next;
  while (p != NULL) {
    printf(" %d ", p->value);
    p = p->next;
    if (p != NULL) {
      printf("->");
    }
  }
  printf("\n");
}

int main(int argc, char *argv[]) {
  freopen("./link_in.txt", "r", stdin);
